package glitch

import data.glitch_lib

weak_ciphers := {"DES", "3DES", "RC4", "MD5", "SHA1", "BLOWFISH", "CBC"}
weak_protocols := {"SSLv2", "SSLv3", "TLS1.0", "TLS1.1", "TLS1_0", "TLS1_1"}
weak_algorithms := {"DES", "3DES", "RC4", "MD5", "SHA1", "BLOWFISH", "AES-128", "RSA-1024", "DSA-1024"}
weak_signatures := {"MD5WITHRSA", "SHA1WITHRSA", "SHA1WITHDSA"}

is_weak_value(val) {
    val.ir_type == "String"
    regex.match("(?i)^(DES|3DES|RC4|MD5|SHA1|BLOWFISH|AES[-_]?128|RSA[-_]?1024|DSA[-_]?128|SSLv2|SSLv3|TLS1[._]0|TLS1[._]1|ELBSecurityPolicy-TLS-1-0|ELBSecurityPolicy-TLS-1-1|CustomAlgo|legacy|insecure)$", val.value)
} else {
    val.ir_type == "Integer"
    val.value <= 1024
    val.value > 0
} else {
    val.ir_type == "Array"
    count(val.value) > 0
    some item
    item = val.value[_]
    is_weak_value(item)
}

check_attribute_name(name) {
    weak_attributes := {"algorithm", "encryption_algorithm", "cipher", "ssl_policy", "tls_version", "signature_algorithm", "hash_algorithm", "protocols", "min_tls_version", "ssl_protocol", "ciphers", "allowed_ciphers", "security_policy", "key_algorithm", "public_key_algorithm", "hashing_algorithm", "password_hash_algorithm", "mac_algorithm", "key_size", "rsa_key_size", "bit_length", "kdf_iterations", "pbkdf2_iterations", "bcrypt_cost", "cost_factor"}
    name == weak_attributes[_]
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    check_attribute_name(attr.name)
    is_weak_value(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of a Broken or Risky Cryptographic Algorithm - Detected weak cryptographic algorithm, cipher, or key length in configuration. (CWE-327)"
    }
}

