package glitch

import data.glitch_lib

# Weak cryptographic algorithms, protocols, and key lengths
weak_ciphers := {"DES", "3DES", "RC4", "MD5", "SHA1", "BLOWFISH", "CBC", "AES-128", "AES128", "TLS_RSA_WITH_AES_128"}
weak_protocols := {"SSLv2", "SSLv3", "TLS1.0", "TLS1.1", "TLS1_0", "TLS1_1"}
weak_algorithms := {"DES", "3DES", "RC4", "MD5", "SHA1", "BLOWFISH", "AES-128", "RSA-1024", "DSA-1024", "md5_crypt", "MD5WITHRSA", "SHA1WITHRSA", "SHA1WITHDSA", "SunX509"}

# Helper to check if a string value is weak
is_weak_string(val) {
    lower_val := lower(val.value)
    weak_protocols[lower_val]
} else {
    lower_val := lower(val.value)
    weak_ciphers[lower_val]
} else {
    lower_val := lower(val.value)
    weak_algorithms[lower_val]
} else {
    # Check for substrings indicating weakness
    regex.match(".*md5.*", lower(val.value))
} else {
    regex.match(".*sha1.*", lower(val.value))
} else {
    regex.match(".*des.*", lower(val.value))
} else {
    regex.match(".*rc4.*", lower(val.value))
} else {
    regex.match(".*ssl.*v[2-3].*", lower(val.value))
} else {
    regex.match(".*tls.*1[._]0.*", lower(val.value))
} else {
    regex.match(".*tls.*1[._]1.*", lower(val.value))
}

# Helper to check for weak key sizes
is_weak_integer(val) {
    val.value <= 1024
    val.value > 0
}

# Recursive traversal for complex values (Hash within Hash, Array within Hash, etc.)
check_value(val) {
    val.ir_type == "String"
    is_weak_string(val)
} else {
    val.ir_type == "Integer"
    is_weak_integer(val)
} else {
    val.ir_type == "Hash"
    some kv
    kv = val.value[_]
    check_value(kv.value)
} else {
    val.ir_type == "Array"
    some item
    item = val.value[_]
    check_value(item)
} else {
    val.ir_type == "Sum"
    check_value(val.left)
} else {
    val.ir_type == "Sum"
    check_value(val.right)
} else {
    val.ir_type == "FunctionCall"
    # Check function arguments for weak values
    some arg
    arg = val.args[_]
    check_value(arg)
} else {
    # Check FunctionCall name itself for weak algorithms
    lower_name := lower(val.name)
    regex.match(".*hash.*md5.*", lower_name)
} else {
    lower_name := lower(val.name)
    regex.match(".*hash.*sha1.*", lower_name)
}

# Check if an attribute name suggests cryptographic configuration
check_attribute_name(name) {
    weak_attributes := {"algorithm", "encryption_algorithm", "cipher", "ssl_policy", "tls_version", "signature_algorithm", "hash_algorithm", "hashing_algorithm", "encrypt", "cipher_suites"}
    name == weak_attributes[_]
} else {
    # Also check for partial matches in attribute names
    regex.match("(?i).*(ssl|tls|cipher|encrypt|algorithm|hash).*", name)
}

# Main rule to detect CWE-327
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    check_attribute_name(attr.name)
    check_value(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of a Broken or Risky Cryptographic Algorithm - Detected weak cryptographic algorithm, cipher, or key length in configuration. (CWE-327)"
    }
}

# Also check variables (e.g., in Chef/Puppet)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    check_attribute_name(var.name)
    check_value(var.value)

    result := {
        "type": "sec_weak_crypt",
        "element": var,
        "path": parent.path,
        "description": "Use of a Broken or Risky Cryptographic Algorithm - Detected weak cryptographic algorithm, cipher, or key length in configuration. (CWE-327)"
    }
}

